/** A Python code block for lesson text. */
const py = (code: string) => "```python\n" + code + "\n```";
/** Output block (plain text, no highlighting). */
const out = (text: string) => "```text\n" + text + "\n```";

const trace = (name: keyof typeof TRACES, extra: Record<string, unknown> = {}): WidgetSpec => ({ type: "trace", props: { ...TRACES[name], ...extra } });

const FRUITS = ["apple", "banana", "cherry", "date"];

/** Test prelude for functions that print: calls go through `_q(f, ...)` so their output stays out of the results. */
const QUIET = `import io as _io, contextlib as _cl
def _q(f, *a):
    with _cl.redirect_stdout(_io.StringIO()):
        return f(*a)
`;

